key:
func removeGuest(id: Int, from list: inout [Guest]) -> Guest? {
    guard let index = list.firstIndex(where: { $0.id == id }) else {
        return nil
    }
    return list.remove(at: index)
}
let removed = removeGuest(id: 8, from: &guests)
assert(removed?.id == 8)
assert(guests.map { $0.id } == [5, 2])
let missing = removeGuest(id: 99, from: &guests)
assert(missing == nil)
assert(guests.count == 2)

firstIndex(where:) ищет позицию по id и возвращает Int?: участника может не быть. remove(at:) удаляет элемент и сдвигает следующие, поэтому порядок [5, 2] сохраняется. По имени искать нельзя: две Иры. Позицию ищем прямо перед удалением — индекс, сохранённый заранее, устареет после любого изменения списка.

