byID[2]?.isBooked = true
print(desks[1].isBooked, byID[2]?.isBooked as Any)
byID[3]?.isBooked = true
print(byID.count)
let removed = byID.removeValue(forKey: 1)
let missing = byID.removeValue(forKey: 7)
